const paths={gold:'M4 7c0-3 16-3 16 0s-16 3-16 0m0 0v10c0 3 16 3 16 0V7M4 12c0 3 16 3 16 0',xp:'m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3Z',damage:'m5 3 14 14m-4 0 4-4M3 21l5-5m-3-3 6 6M16 3l5 5-9 9',vision:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12m10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',support:'M9 3h6v6h6v6h-6v6H9v-6H3V9h6Z',control:'M6 3v8a6 6 0 0 0 12 0V3M6 7h4M14 7h4',neutral:'M4 18V9m8 9V3m8 15v-6'};
export function metricTone(key){if(/gold|gpm|last_hits|добив|золот/i.test(key))return 'gold';if(/xp|опыт/i.test(key))return 'xp';if(/damage|kills|deaths|урон|убий|смерт/i.test(key))return 'damage';if(/obs|sen|вард|обсер|сентри/i.test(key))return 'vision';if(/heal|assist|stack|леч|помощ|стак/i.test(key))return 'support';if(/stun|контрол|оглуш/i.test(key))return 'control';return 'neutral';}
export function metricIcon(key){const tone=metricTone(key);return `<svg class="metric-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[tone]}"/></svg>`;}
